---DECL---
declare module 'virtual:feature-flags' {
  export interface FeatureFlagsShape {
    readonly "checkoutV2": boolean
    readonly "theme": string
  }
}

import { watch, type FSWatcher } from 'node:fs'
import { readFile, writeFile } from 'node:fs/promises'
import { relative, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

import type {
  HmrContext,
  ModuleNode,
  Plugin,
  ResolvedConfig,
  ViteDevServer,
} from 'vite'

export type FeatureFlagPrimitive = boolean | number | string | null

export interface FeatureFlagsShape {
  readonly [key: string]: FeatureFlagPrimitive
}

export interface FeatureFlagsOptions {
  source: string | URL
  expose: readonly string[]
  declarationFile?: string
}

interface CachedSnapshot {
  declaration: string
  exposed: FeatureFlagsShape
}

const PUBLIC_MODULE_ID = 'virtual:feature-flags'
const RESOLVED_PUBLIC_MODULE_ID = '\0virtual:feature-flags'
const DEFAULT_DECLARATION_FILE = 'src/feature-flags.d.ts'
const SECRET_NAME_PATTERN = /(secret|token|password|private[-_]?key|access[-_]?key)/i

export function featureFlags(options: FeatureFlagsOptions): Plugin {
  const expose = [...new Set(options.expose)]
  const sourcePath = toFilePath(options.source)
  const declarationFile = options.declarationFile ?? DEFAULT_DECLARATION_FILE

  let config: ResolvedConfig | undefined
  let server: ViteDevServer | undefined
  let cachedSnapshot: CachedSnapshot | undefined
  let lastDeclaration = ''
  let fileWatcher: FSWatcher | undefined

  const invalidate = () => {
    cachedSnapshot = undefined
  }

  const getDeclarationPath = () => {
    const root = config?.root ?? process.cwd()
    return resolve(root, declarationFile)
  }

  const getSnapshot = async (): Promise<CachedSnapshot> => {
    if (cachedSnapshot) {
      return cachedSnapshot
    }

    const sourceText = await readFile(sourcePath, 'utf8')
    const parsed = parseFlags(sourceText, sourcePath)
    const exposed = pickExposedFlags(parsed, expose, sourcePath)

    cachedSnapshot = {
      declaration: renderDeclaration(exposed),
      exposed,
    }
    return cachedSnapshot
  }

  const syncDeclarationFile = async () => {
    const snapshot = await getSnapshot()
    if (snapshot.declaration === lastDeclaration) {
      return
    }

    await writeFile(getDeclarationPath(), snapshot.declaration, 'utf8')
    lastDeclaration = snapshot.declaration
  }

  const invalidateVirtualModule = (module: ModuleNode | undefined) => {
    if (!server || !module) {
      return
    }
    server.moduleGraph.invalidateModule(module)
  }

  const onSourceChange = async () => {
    invalidate()

    try {
      await syncDeclarationFile()
    } catch (error) {
      const normalizedError = error instanceof Error ? error : new Error(String(error))
      server?.config.logger.error(normalizedError.message, { error: normalizedError })
      return
    }

    if (!server) {
      return
    }

    const module = server.moduleGraph.getModuleById(RESOLVED_PUBLIC_MODULE_ID)
    invalidateVirtualModule(module)
    server.watcher.emit('change', sourcePath)
    server.ws.send({ type: 'full-reload', path: '*' })
  }

  const ensureFileWatcher = () => {
    if (fileWatcher) {
      return
    }

    fileWatcher = watch(sourcePath, () => {
      void onSourceChange()
    })
  }

  const closeFileWatcher = () => {
    fileWatcher?.close()
    fileWatcher = undefined
  }

  return {
    name: 'feature-flags',

    async configResolved(resolvedConfig) {
      config = resolvedConfig
      await syncDeclarationFile()
    },

    async buildStart() {
      this.addWatchFile(sourcePath)
      await syncDeclarationFile()
    },

    configureServer(configuredServer) {
      server = configuredServer
      configuredServer.watcher.add(sourcePath)
      ensureFileWatcher()
    },

    resolveId(id) {
      if (id === PUBLIC_MODULE_ID) {
        return RESOLVED_PUBLIC_MODULE_ID
      }
      return null
    },

    async load(id) {
      if (id !== RESOLVED_PUBLIC_MODULE_ID) {
        return null
      }

      const snapshot = await getSnapshot()
      return {
        code: renderVirtualModule(snapshot.exposed),
        map: {
          version: 3,
          file: PUBLIC_MODULE_ID,
          sources: [relative(config?.root ?? process.cwd(), sourcePath)],
          names: [],
          mappings: '',
        },
      }
    },

    watchChange(id) {
      if (resolve(id) === sourcePath) {
        invalidate()
      }
    },

    async handleHotUpdate(context: HmrContext) {
      if (resolve(context.file) !== sourcePath) {
        return
      }

      invalidate()
      await syncDeclarationFile()

      const module = context.server.moduleGraph.getModuleById(RESOLVED_PUBLIC_MODULE_ID)
      invalidateVirtualModule(module)
      return module ? [module] : []
    },

    closeBundle() {
      closeFileWatcher()
    },
  }
}

function toFilePath(source: string | URL): string {
  return resolve(source instanceof URL ? fileURLToPath(source) : source)
}

function parseFlags(sourceText: string, sourcePath: string): Record<string, unknown> {
  let parsed: unknown

  try {
    parsed = JSON.parse(sourceText)
  } catch (error) {
    throw diagnostic(
      `Invalid JSON in ${sourcePath}.`,
      'Fix the JSON syntax so the plugin can generate the virtual module.',
      error,
    )
  }

  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    throw diagnostic(
      `Expected ${sourcePath} to contain a JSON object.`,
      'Use a flat object such as { "checkoutV2": true }.',
    )
  }

  return parsed as Record<string, unknown>
}

function pickExposedFlags(
  parsed: Record<string, unknown>,
  expose: readonly string[],
  sourcePath: string,
): FeatureFlagsShape {
  if (expose.length === 0) {
    throw diagnostic(
      'The "expose" option is empty.',
      'List the client-safe keys to publish, for example expose: ["checkoutV2"].',
    )
  }

  const missing = expose.filter((key) => !(key in parsed))
  if (missing.length > 0) {
    throw diagnostic(
      `Missing exposed flags in ${sourcePath}: ${missing.join(', ')}.`,
      'Add the missing keys to the JSON file or remove them from "expose".',
    )
  }

  const suspicious = expose.filter((key) => SECRET_NAME_PATTERN.test(key))
  if (suspicious.length > 0) {
    throw diagnostic(
      `Refusing to expose secret-like keys from ${sourcePath}: ${suspicious.join(', ')}.`,
      'Move secrets to server-only configuration or rename the public flags to avoid leaking credentials.',
    )
  }

  const exposed: Record<string, FeatureFlagPrimitive> = {}
  for (const key of expose) {
    const value = parsed[key]
    if (!isFeatureFlagPrimitive(value)) {
      throw diagnostic(
        `Unsupported value for "${key}" in ${sourcePath}.`,
        'Feature flags must be string, number, boolean, or null so dev, build, and HMR stay deterministic.',
      )
    }
    exposed[key] = value
  }


